        for col in range(n):
            if can_harvest():
                harvest()
            if get_entity_type() == None:
                plant(Entities.Carrot)
            if get_water() < 0.3 and num_items(Items.Water) > 0:
                use_item(Items.Water)
            move(East)
        move(North)

for i in range(rounds):
